import { _decorator, Color, Component, Graphics, Label } from 'cc';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { GRID_SIZE } from '../Config/GridConfig';

const { ccclass } = _decorator;

@ccclass('BuildingView')
export class BuildingView extends Component implements EntityView {

    private _building: BuildingEntity | null = null;
    private _g: Graphics = null!;
    private _label: Label = null!;

    onLoad() {
        this._g = this.node.addComponent(Graphics);
        this._label = this.node.addComponent(Label);
        this._label.fontSize = 20;
        this._label.lineHeight = 24;
        this._label.color = new Color(255, 255, 255, 255);
    }

    bind(entity: Entity): void {
        this._building = entity as BuildingEntity;
        this._drawBase();
        this.sync(0);
    }

    sync(_dt: number): void {
        if (!this._building) return;
        this.node.setPosition(this._building.x, this._building.y);

        // 相性加成用金色，否则白色
        this._label.color = this._building.synergyMultiplier > 1
            ? new Color(255, 220, 100, 255)
            : new Color(255, 255, 255, 255);

        this._label.string = `Lv${this._building.level}\n${Math.floor(this._building.pendingIncome)}`;
    }

    unbind(): void {
        this._building = null;
    }

    private _drawBase(): void {
        this._g.clear();
        this._g.fillColor = new Color(60, 140, 90, 255);
        const half = GRID_SIZE / 2 - 6;
        this._g.rect(-half, -half, half * 2, half * 2);
        this._g.fill();
    }
}